import fs from "node:fs";
import {buildReview} from "./review-adversarial-r4-20261102.mjs";
const r=await buildReview(),c=r.content;
const cell=s=>String(s??"").replaceAll("|","\\|").replaceAll("\n"," ");
const sources=["# Sources for fourth author revision after independent review three","",
 "Access/check date: 2026-11-02. These are bibliographic records and original atomic factual syntheses, not stored article text, excerpts, tables, figures, algorithms or source questions. All new clinical claims, concepts, profiles and question versions remain needs_clinician_review. Melissa Rowland is the named clinical sign-off.","",
 `${c.QUESTION_QUALITY_ADVERSARIAL_R4_SOURCES.length} scoped records support ${c.QUESTION_QUALITY_ADVERSARIAL_R4_CLAIMS.length} added claims. Reused publications are identified individually; new record IDs do not create independent corroboration. Medical authority is recorded separately from license permissiveness. Management claims with one adequate source or low-quality support retain that limitation. Constructed patient observations and teaching-study values are not evidence-backed clinical cutoffs.`,"",
 "Full primary checks included ACG physiologic testing, HerniaSurge, ATA2025, ESMO melanoma, NCI melanoma, ACR liver characterization, ESSR local imaging, ESGE subepithelial lesions, BSH marginal-zone lymphoma, EUSOBI biopsy, KSGE collections, current iLATAM2026 and ESGE ulcer2026, together with the DailyMed flumazenil label. The independent gastric-MALT review was read in its licensed full original PDF. Metadata records distinguish prior same-day verification from fresh full-document access.","",
 "Several direct publisher/PMC routes returned 403, a browser check, or unavailable PDFs. Public primary-document mirrors are listed in the individual records. No bypass, paywalled snippet, commercial bank, recalled board item, SCORE, UpToDate, AccessSurgery or proprietary textbook supplied evidence. The ASBrS document is explicitly archived 2024, cross-check only. The ESGE2026 correction was identified but its separate PDF was unavailable; no claim that every correction/supplement was reviewed is made.","",
 "## Source records",""];
for(const s of c.QUESTION_QUALITY_ADVERSARIAL_R4_SOURCES)sources.push("### "+s.id,"",
 "- Complete citation: "+s.completeCitation,
 "- Organization/journal: "+s.organizationOrJournal,
 "- Authors: "+s.authors.join("; "),
 "- Year: "+(s.publicationYear??"live document; no fixed edition year")+". DOI: "+(s.doi??"none in this record")+". PMID: "+(s.pmid??"none in this record")+".",
 "- Official URL: ["+s.title+"]("+s.officialUrl+"). Access/check date: "+s.accessedOn+".",
 "- Source class: "+s.sourceClass+". Intended use: "+s.usageRole+".",
 "- License/reuse: "+s.licenseLabel+" / "+s.reuseStatus+". "+s.reuseNotes,
 "- Medical authority and intended factual use: "+s.authorityAssessment,
 "- Supported atomic claims: "+s.evidenceClaimIds.join(", ")+".","");
sources.push("## Atomic claims and mappings","",
 "Each record has lastCheckedOn 2026-11-02, AI-assisted drafting, lastClinicianReview null, and reviewStatus needs_clinician_review. Existing claim mappings remain in historical modules; new facts are additive. Exact clinical observations are fictional unless explicitly labelled as a guideline criterion. No medication dose, universal response deadline or new imaging threshold is invented.","",
 "| Claim | Original factual synthesis | Source IDs | Category / certainty | Limitation | Revised items |",
 "| --- | --- | --- | --- | --- | --- |");
for(const claim of c.QUESTION_QUALITY_ADVERSARIAL_R4_CLAIMS)sources.push("| "+[claim.id,claim.statement,claim.sourceIds.join(", "),claim.evidenceCategory+" / "+claim.certainty,claim.limitation,r.all.filter(p=>p.supportingEvidenceClaimIds?.includes(claim.id)).map(p=>p.id).join(", ")].map(cell).join(" | ")+" |");
sources.push("","## Excluded or insufficiently accessed candidates","",
 "No new claim uses the inaccessible ICCR melanoma article, EADO diagnostic PDF, NICE melanoma page, RCPA material, AAD paywalled guideline, or inaccessible AGA/ASGE SEL document. Existing properly mapped historical claims remain identified as historical. No snippet was substituted for the missing full document. Earlier OpenStax material remains excluded because its terms separately restricted AI ingestion; the temporary pandemic-licensed muscle review remains excluded. See the preceding source ledger for those exclusion metadata. No prohibited source text is retained.","");
fs.writeFileSync("docs/research/sources-question-adversarial-r4-20261102.md",sources.join("\n"));

const response=["# Fourth author revision: response to independent review three","",
 "2026-11-02. Input: [independent review three](question-batch1-adversarial-review3-20261102.json). Current machine-readable packets: [round three](question-round3-20261102.json) and [batch one](question-batch1-20261102.json). Key shown first for review only; runtime answer choices randomize.","",
 "Preserved: all 27 exact PASS questions, their presentation/task/options/update/exhibit and profiles; all three ACCEPT_BASIC versions (B01, B10, B29); and Melissa's eleven exact historical approvals. The other 45 returned items have new v7 drafts. All 32 rejected basic labels and justifications are removed. No revised item is relabelled basic. Every new question, concept, clinical claim and presentation remains needs_clinician_review.","",
 "**B29 conflict remains open:** review three calls its educational role ACCEPT_BASIC but its recovery key REVISE. Instruction 1 says to keep accepted-basic wording unchanged. B29 therefore retains its exact version and basicAccepted true, but pipelinePassed false, with the unresolved recovery criterion stated in reviewResponse. A clarification was requested; no answer is inferred from silence. The prepared repair is not applied.","",
 "The 394 third-review notes (47 cues, 223 fairness, 124 suggestions) are individually indexed in reviewResponse. For revised items, responses identify the old phrase's removal/retention, relevant concrete changes, the decisive finding, closest error and unresolved clinical/source limitation. Alternative suggestions are not treated as cumulative requirements where they are mutually exclusive. Author self-checks do not grant independent PASS or prove resident difficulty.","",
 "## Exact independent passes","",
 "| Item | Frozen variant | Basic role accepted | Independent difficulty prediction |","| --- | --- | --- | --- |"];
for(const p of r.all.filter(p=>p.pipelinePassed))response.push("| "+[p.id,p.after.variantId,p.basicAccepted?"yes":"no",p.independentReview.difficultyPrediction].map(cell).join(" | ")+" |");
response.push("","## Returned decisions","",
 "| Item | New variant | Scored inference | Specific changes | Remaining clinical review |","| --- | --- | --- | --- | --- |");
for(const p of r.all.filter(p=>!p.pipelinePassed&&p.id!=="B29"))response.push("| "+[p.id,p.after.variantId,p.inference,p.reviewActions.join(" "),p.reviewResponse.selfCheck.remainingReview].map(cell).join(" | ")+" |");
response.push("","## Explicit changes of clinical meaning","",
 "Eighteen new concept versions cover 42 revisions; B03, B24 and B36 apply their existing objectives. All 370 old concept definitions remain exact; the full catalog now has 388 definitions. The inventory's concept total counts concepts referenced by live nodes, not every retained catalog definition. New application concepts have educationalTier 1 as an editorial designation; their facility gate, patient acuity and service capability remain separate.","",
 "| New concept | Previous concept | Items | Changed objective and reason |","| --- | --- | --- | --- |");
for(const v of c.QUESTION_QUALITY_ADVERSARIAL_R4_AUTHORING_CONCEPTS)response.push("| "+[v.id,v.previousConceptId,v.revisedItemIds.join(", "),v.learningObjective+" "+v.versioningReason].map(cell).join(" | ")+" |");
response.push("","The existing selector requires every concept in a pair to be unseen or due. A future-due companion can block either position; either an early or later eligible concept can draw the pair. Sixteen new versions have only paired coverage. B09 has a standalone clinical case, and B26 is a standalone employee discussion. Fixed-time unseen-supply snapshots expose waiting concepts and retained old catalog identities; they do not prove permanent unreachability. Manager should decide whether later authoring adds standalone coverage. No selector, routing or history migration changes.","",
 "## Clinical and cue limits to inspect","",
 "- A25-context deliberately changes the scored objective to the indication-dependent flumazenil contraindication. The discarded oral/IV prevention draft repeated the exact rule already taught by the unchanged preceding PASS question. The new seizure-course interpretation and reversal plan especially need anesthesia/neurology review.",
 "- B05/B07 compare a mistargeted/incomplete ultrasound with adequate dynamic assessment; B06/B08 compare adequate negative scans with cross-sectional problem solving and competing muscle pain. MRI is not described as universally wrong after an incomplete scan. A clinician must verify local single-best ranking and pain attribution; hernia repair never promises to cure separate pain.",
 "- B09 uses the existing thyroid-FNA service for cervical-node FNA. Its terminal binding is explicit, but the service's display scope should be reviewed by the manager/thyroid clinician. No new service or routing implementation is added.",
 "- B11/B12/B17/B18 require a representative residual-lesion specimen or nodal sample before applying familiar depth rules. The partial specimen is not treated as sufficient when its target/deep edge is missing. Exact completion technique and current melanoma pathways remain specialist decisions.",
 "- B14 uses a fictional 8-mm liver focus: the full ACR subcentimeter scenario was checked, rather than misusing recommendations for lesions above 1 cm. MRI is preferred here; biopsy and PET are not declared universally forbidden. B15 retains usable abdominal/pelvic MRI and supplies actual partial chest coverage.",
 "- B19/B20 keep the passed later route/target tasks exact and test different acquisition defects. B21/B22 preserve shared passed lipoma presentations. Instead of introducing unresolved fourth-layer discordance that would invalidate their passed no-follow-up companions, the new task evaluates normal overlying mucosa versus the submucosal diagnosis and need for another specimen. This remains a particular difficulty concern for independent re-review; no basic exception is claimed.",
 "- B24 removes the unsupported ranking between repeat endoscopy and molecular testing. Remaining block/site information is given, and the task now asks what the existing findings establish. Preserved glands do not exclude MALT. B25/B30 distinguish dispersed large cells, molecular persistence, and actual clinical/histologic response from transformation/progression.",
 "- B32–B35 replace repeated IV-contrast/pseudocyst recall with arterial bleeding, nonliquid necrosis, partial duct leak and complete duct disconnection. Source limitations, apposition, viable upstream gland and persistence of symptoms are explicit. Long-term plastic-stent support is low-quality; exact intervention needs specialist review.",
 "- B36 asks for a next-cycle comparison. It requires locating added form-entry work and separating an entry-method change from a simultaneous record-source change; both sources and modes are available and review is retained. It does not preselect a prefill source or claim proven benefit. B37 uses an actual missed-target benign core rather than a future-staging hint. B40 uses one coherent duodenal-ulcer course and distinguishes recurrent bleeding after success from failed repeat therapy; first-task feedback does not give the second answer.","",
 "## Advisory lint and compatibility","",
 `Same linter on both sides: whole bank ${r.comparison.wholeBank.before.findings} to ${r.comparison.wholeBank.after.findings} findings, ${r.comparison.wholeBank.before.variantsWithFindings} to ${r.comparison.wholeBank.after.variantsWithFindings} flagged variants. Selected 73: ${r.comparison.selected.before.findings} to ${r.comparison.selected.after.findings} findings, ${r.comparison.selected.before.variantsWithFindings} to ${r.comparison.selected.after.variantsWithFindings} flagged variants. Clinical application can increase lexical overlaps from named findings/tests; these warnings are retained with exact evidence for independent attack. Warning totals are neither difficulty nor fairness measurements. No warning suppression or option padding is used.`,"",
 "All 1,669 entry timing rows remain exact; 45 additive rows make 1,714. Six new exact choice-order records retain all older source records: B09 has the explicit new existing FNA contract, B18 is a future planned biopsy, and four pancreatic specialist plans retain nonexecution with updated preview profiles. Seven keyed service changes are explicit in clinicalBinding: B06, B08, B09, B14-context, B33-context, B34-context and B35-context. No duration value, save format, queue rule or frozen encounter is rewritten. The active bank has 1,451 timed choices and 138 terminal timed keys (22 and two fewer respectively); Level 3 still covers 80 nodes and now 318 choices because A25-context has three linked reversal choices rather than four independent-axis plans.","",
 "The canonical age/sex and every revised profile use the existing {ageYears}/{sexNoun} template mechanism. A player test caught the unsupported shorthand token; the source templates were corrected and a regression check covers resolution. No player production code changed.","",
 "Question quality uses the standard, advisory lint, owner/clinician review and voluntary tester flags. There is no correctness collection, statistical input, sample threshold, analytic gate or new player-data handling. Nothing ships from this worker. Validation and exact Level 5 inputs are recorded in the round-four handoff; manager owns acceptance, clinical review-page publication, any missing standalone scope and the actual rebind.","");
fs.writeFileSync("docs/research/question-adversarial-round4-response-20261102.md",response.join("\n"));
